export function log(s,text){s.log.push(text);s.log=s.log.slice(-70);}
export function blocked(s,c,x,y,ignore){return x<0||y<0||x>=c.map.width||y>=c.map.height||c.map.walls.some(p=>p[0]===x&&p[1]===y)&&heightOf(c,unit(s,ignore)||{z:-1001})!==heightAt(c,{x,y})||(c.map.gaps||[]).some(p=>p[0]===x&&p[1]===y)||(!s.door&&x===c.map.door[0]&&y===c.map.door[1])||s.units.some(u=>u.id!==ignore&&alive(u)&&u.x===x&&u.y===y&&(u.side==='party'||s.found));}
export function los(s,c,a,b){let x=a.x,y=a.y,dx=Math.abs(b.x-x),dy=-Math.abs(b.y-y),sx=x<b.x?1:-1,sy=y<b.y?1:-1,err=dx+dy;const n=Math.max(dx,-dy)||1,az=heightOf(c,a)+5,bz=heightOf(c,b)+5;let step=0;while(x!==b.x||y!==b.y){const e=err*2;if(e>=dy){err+=dy;x+=sx;}if(e<=dx){err+=dx;y+=sy;}step++;if(x===b.x&&y===b.y)return true;const eye=az+(bz-az)*step/n,wall=c.map.walls.some(p=>p[0]===x&&p[1]===y)||(!s.door&&x===c.map.door[0]&&y===c.map.door[1]);if((wall&&x===c.map.door[0]&&y===c.map.door[1]?c.map.wallHeight||15:heightAt(c,{x,y}))>=eye)return false;}return true;}
export function cover(s,c,a,b){if(!los(s,c,a,b))return Infinity;if(tileTerrain(c,b)?.parapet&&heightOf(c,a)<heightOf(c,b))return 2;return s.units.some(u=>alive(u)&&u.id!==a.id&&u.id!==b.id&&horizontal(a,u)<horizontal(a,b)&&Math.abs((b.x-a.x)*(u.y-a.y)-(b.y-a.y)*(u.x-a.x))<1&&heightOf(c,u)+5>=heightOf(c,a)+5+(heightOf(c,b)-heightOf(c,a))*horizontal(a,u)/Math.max(1,horizontal(a,b))-2)?2:0;}
export function roll(s,u,stat,adv=0,bonus=0){const a=rng(s),b=adv?rng(s):a;return {natural:adv>0?Math.max(a,b):adv<0?Math.min(a,b):a,total:(adv>0?Math.max(a,b):adv<0?Math.min(a,b):a)+mod(u.scores[stat])+bonus+(u.bless?dice(s,1,4):0)};}
function damage(s,u,n,c=null){if(u.dead)return;const absorb=Math.min(u.temp||0,n);u.temp-=absorb;n-=absorb;if(u.hp===0&&n>0){u.death.fail+=1;if(u.death.fail>=3)u.dead=true;}const oldHp=u.hp;u.hp=Math.max(0,u.hp-n);if(!u.hp&&n-oldHp>=u.maxHp)u.dead=true;if(!u.hp){u.prone=true;u.reaction=0;clearConcentration(s,u);if(u.side==='enemy')u.dead=true;}if(n&&u.concentration){const dc=Math.max(10,Math.floor(n/2));if(roll(s,u,'CON',0,u.class==='fighter'?2:0).total<dc){log(s,u.name+'專注中斷。');clearConcentration(s,u);}}if(!alive(u)&&u.climbing&&c)fallFromClimb(s,c,u);}
