function result(s){cleanGrapples(s);if(s.page!=='battle')return;if(!s.units.some(u=>u.side==='enemy'&&alive(u))){s.minute=effectNow(s);s.page='explore';s.result='win';s.pending=null;delete s.readyEvents;delete s.reactionWalks;s.units.forEach(u=>{delete u.ready;delete u.helpedBy;delete u.skillHelp;u.shieldSpell=false;if(u.concentration?.readied)clearConcentration(s,u);});log(s,'盜賊敗退。石室安全了，去找信物。');}else if(!s.units.some(u=>u.side==='party'&&alive(u))){s.minute=effectNow(s);s.page='defeat';s.result='lose';s.pending=null;delete s.readyEvents;delete s.reactionWalks;for(const u of s.units){if(u.concentration?.readied)clearConcentration(s,u);delete u.ready;}log(s,'小隊已無人能行動。可讀取存檔重新出發。');}}
