export function spellArea(s,c,u,spell,aim){const sp=c.spells[spell];if(!areaKind(sp)||!aim)return {cells:[],units:[]};const cells=areaCells(c,u,sp.kind,aim,(a,b)=>los(s,c,a,b));const units=s.units.filter(v=>!v.dead&&v.id!==u.id&&areaContains(u,v,sp.kind,aim)&&los(s,c,u,v));return {cells,units};}
