export function jumpCost(s,c,u,a){if(a.type==='high')return a.height;return distance(u,a)*5+(difficult(c,a)?5:0);}
function jumpProblem(s,c,u,a){if(u.climbing)return '攀爬中不能起跳';if(!speed(s,u)||u.prone)return '須能站立移動才能跳躍';if(heldTargets(s,u).length)return '本版拖行被擒抱者時須先放開，才能跳躍';const limits=jumpLimits(u);if(a.type==='high'){if(!Number.isInteger(a.height)||a.height<=0||a.height>limits.high)return '超出跳高高度';return s.page==='battle'&&u.move<a.height?'跳躍所需移動不足':'';}if(a.type!=='long')return '請選跳遠或跳高';if(!Number.isInteger(a.x)||!Number.isInteger(a.y)||distance(u,a)<1)return '請選跳躍落點';if(heightAt(c,a)!==heightOf(c,u))return '高低差落點須選跳上或跳下';const route=jumpRoute(u,a);if(!route)return '跳遠須沿直線';if(distance(u,a)*5>limits.long)return '超出跳遠距離；先走十呎可助跑';if(s.page==='battle'&&u.move<jumpCost(s,c,u,a))return '跳躍所需移動不足';const virtual={...u};for(let i=0;i<route.length;i++){const err=jumpStepProblem(s,c,virtual,route[i],i===route.length-1);if(err)return err;Object.assign(virtual,route[i]);}return '';}
